INSERT INTO public.memorial_sisters (id, name, title, birth_date, profession_date, departure_date, photo, communities, ministry, biography, quote, burial_place) VALUES
('mother-regina-woroniecka', 'Rev. Mother Regina Woroniecka SCS', 'Foundress & Mother General', '1920-03-24', '1948-08-15', '2002-12-18', 'images/memorial/mother_regina.jpg', '["Marianiketan Mariyapura", "Generalate Mysore", "Bydgoszcz"]'::jsonb, 'Foundress, Spiritual Directress, Formation & General Leadership', 'Rev. Mother Regina Woroniecka, born in Poland and formed in the Ursuline missionary tradition, felt an irresistible calling to serve the poorest rural families of Southern India. In 1976, guided by Bishop Mathias Fernandes of Mysore, she established the Satyaseva Catechist Sisters of the Families in Mariyapura. Her life was a radiant beacon of sacrificial charity, contemplative prayer, and total obedience to God''s providence.', 'Service to Truth — Satyaseva — is to bring Christ into the quiet domestic hearth of every suffering and seeking family.', 'Mariyapura Motherhouse Cemetery, Karnataka, India'),
('sr-clare', 'Sr. Clare SCS', 'Pillar of Catechesis & Family Apostolate', '1954-04-12', '1982-05-15', '2024-06-15', 'images/memorial/sr_clare.jpg', '["Marianiketan Mariyapura", "Generalate Bangalore", "Prakashpalya"]'::jsonb, 'Catechesis, Family Ministry, Parish Animation & Prayer Leadership', 'Sr. Clare was a beloved, devoted member of the Satyaseva Sisters who served the congregation with unwavering gentleness, joy, and deep pastoral commitment to families and children.', 'Let love and humility guide every step of our mission.', 'Mariyapura Motherhouse Cemetery, Karnataka, India'),
('sr-justin', 'Sr. Justin SCS', 'Apostle of Quiet Prayer & Educational Mission', '1962-09-10', '1989-06-20', '2020-07-25', 'images/memorial/sr_justin.jpg', '["Sacred Heart Convent Maruthavu", "Generalate Bangalore"]'::jsonb, 'Education, Remedial Schooling & Family Accompaniment', 'Sr. Justin dedicated her life to the education of children and accompanied countless families through compassionate home visits and prayer.', 'In silent trust, God works wonders in humble hearts.', 'Maruthavu Catholic Cemetery, Kerala'),
('sr-james', 'Sr. James SCS', 'Minister of Sacraments & Humble Service', '1968-11-25', '1995-05-10', '2022-02-18', 'images/memorial/sr_james.jpg', '["St. Joseph Convent Prakashpalya", "Christ the King Jaggeri"]'::jsonb, 'Care for Sick & Elderly, Sacristy Service & Family Prayer Circles', 'With radiant warmth and selfless charity, Sr. James touched the hearts of the sick and elderly, bringing Christ''s peace to every household she entered.', 'To serve the little ones is to serve Christ Himself.', 'Prakashpalya Parish Cemetery, Karnataka'),
('sr-rosalia', 'Sr. Rosalia SCS', 'Devoted Missionary & Caregiver of Families', '1951-03-08', '1980-04-18', '2016-10-18', 'images/memorial/sr_rosalia.jpg', '["Karunaniketan Maranahalli", "Marianiketan Mariyapura"]'::jsonb, 'Slum Outreach, Crèche Ministry & Women''s Empowerment', 'Sr. Rosalia poured her energy into village outreach, rural welfare, and supporting women and children across the mission stations.', 'Where there is love, there is God.', 'Mariyapura Motherhouse Cemetery, Karnataka'),
('sr-tresa-mary', 'Sr. Tresa Mary SCS', 'Contemplative Heart & Steadfast Educator', '1953-08-14', '1983-02-11', '2022-08-06', 'images/memorial/sr_tresa_mary.jpg', '["St. Jude''s Convent Mariamangala", "Generalate Mysore"]'::jsonb, 'Eucharistic Adoration, Senior Sister Care & Pastoral Mentoring', 'Sr. Tresa Mary served the congregation through her profound spirit of adoration, patience in teaching, and maternal solicitude for the poorest.', 'Perpetual adoration is the heartbeat of our spiritual family.', 'Mariamangala Cemetery, Karnataka'),
('sr-annamma', 'Sr. Annamma SCS', 'Early Mission Pioneer & Pastoral Servant', '1945-02-17', '1977-10-04', '2006-04-27', 'images/memorial/sr_annamma.jpg', '["Marianiketan Mariyapura", "St. Joseph Convent Prakashpalya"]'::jsonb, 'Founding Mission Outreach, Catechetical Instruction & Village Visits', 'One of the steadfast early pillars who walked the rural trails in faith beside Mother Regina, planting seeds of hope and Christian solidarity among needy families.', 'God''s providence never fails those who put their trust in Him.', 'Mariyapura Motherhouse Cemetery, Karnataka')
INSERT INTO public.events (id, title, date, time, location, description) VALUES
(5, '50th Golden Jubilee of Foundation (1976 – 2026)', '2026-11-21', '09:30 AM', 'SCS Generalate & Motherhouse, Bogadi, Mysore', 'Solemn Eucharistic Thanksgiving Celebration and jubilee assembly commemorating fifty golden years of selfless family catechesis, rural home visits, and educational service in India, Germany, and Poland.'),
(6, 'Feast of the Holy Family & Annual Diocesan Family Gathering', '2026-12-27', '10:00 AM', 'St. Philomena''s Cathedral Grounds & SCS Family Centre, Mysore', 'Special Holy Mass and blessing of families, honoring grandparents and catechists. Interactive seminar on Christian family values and harmony in contemporary society.'),
(7, 'National Workshop for Catechists & Parish Animators', '2027-01-16', '09:00 AM', 'Pastoral Centre & Generalate Hall, Bangalore', 'A three-day intensive formation workshop on innovative rural catechesis, sacramental preparation for remote hamlets, and family pastoral accompaniment.'),
(8, 'Vocations ''Come & See'' Discernment Camp', '2027-02-12', '08:30 AM', 'Satyaseva Formation House, Hunsur, Karnataka', 'An open weekend of prayer, discernment, community life, and spiritual accompaniment for young Catholic women seeking God''s will and religious vocation.'),
(9, 'Feast of St. Joseph the Worker & Blessing of Mission Stations', '2027-05-01', '07:00 AM', 'All 32 SCS Community Convents & Substations', 'Patronal feast of working apostolates with special prayers for daily wage laborers, migrant families, and women''s self-help tailoring cooperative units.'),
(10, 'Solemnity of the Most Sacred Heart of Jesus', '2027-06-04', '06:30 AM', 'Generalate Chapel, Mysore', 'Congregation-wide Renewal of Vows and adoration vigil, entrusting all mission communities, benefactors, and foster children to the Sacred Heart of Jesus.'),
(11, 'Inauguration of the Hunsur Rural Learning & Health Center', '2026-08-15', '11:00 AM', 'St. Joseph Convent, Hunsur', 'Blessing and opening of the newly expanded classroom building and free health checkup clinic for surrounding tribal and agrarian village families.')
